#!/bin/bash
set -eo pipefail
umask 077
test "$(id -un)" = sunyiq
for parent in / /data1 /data1/home /data1/home/sunyiq; do
  test -d "$parent"
  test ! -L "$parent"
  test "$(readlink -e "$parent")" = "$parent"
done
test ! -e '/data1/home/sunyiq/china_us_negative_comparison_20261007_001'
test ! -L '/data1/home/sunyiq/china_us_negative_comparison_20261007_001'
mkdir '/data1/home/sunyiq/china_us_negative_comparison_20261007_001'
mkdir '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/src' '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/contracts' '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/logs'
set -o noclobber
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/src/analyze_us_saved_results_v1.py'
printf '%s  %s\n' '9e158da4861b06e6594d3385ddacd71bf38dc3fff824e7a748a51cc5375ac30b' '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/src/analyze_us_saved_results_v1.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/contracts/US_SAVED_RESULTS_CONTRACT_v1.json'
printf '%s  %s\n' '669cc85f7b3cd1352a0ec26d3410d57496a61644de78e93a826bc4c2295f7609' '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/contracts/US_SAVED_RESULTS_CONTRACT_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/us_statistics_v1.sbatch'
printf '%s  %s\n' '2eb8847e545781bceb7d4e1734ca5d8e7b7e2da770e45eded1f4029a7c9387dd' '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/us_statistics_v1.sbatch' | sha256sum -c -
job=$(sbatch --parsable '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/us_statistics_v1.sbatch')
case "$job" in ''|*[!0-9]*) printf 'UNEXPECTED_JOB_RECEIPT\n' >&2; exit 1;; esac
printf '%s\n' "$job" > '/data1/home/sunyiq/china_us_negative_comparison_20261007_001/job_id.txt'
printf 'US_STATISTICS_ROOT=/data1/home/sunyiq/china_us_negative_comparison_20261007_001\nUS_STATISTICS_JOB_ID=%s\nUS_STATISTICS_SUBMITTED_ONCE\n' "$job"
